package com.mycompany.rentalmanagement.dao;
import com.mycompany.rentalmanagement.DBConnection;import java.sql.*;import java.util.*;
public class VehicleDAO {
 public List<Map<String,Object>> list(String q)throws SQLException{List<Map<String,Object>> a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM vehicles WHERE registration_number LIKE ? OR make LIKE ? OR model LIKE ? ORDER BY id DESC")){for(int i=1;i<=3;i++)p.setString(i,DAOUtil.like(q));try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();for(String k:new String[]{"id","registration_number","make","model","vehicle_type","model_year","daily_rate","status","notes"})m.put(k,r.getObject(k));a.add(m);}}}return a;}
 public Map<String,Object> get(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM vehicles WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())return null;Map<String,Object> m=new LinkedHashMap<>();for(String k:new String[]{"id","registration_number","make","model","vehicle_type","model_year","daily_rate","status","notes"})m.put(k,r.getObject(k));return m;}}}
 public void save(long id,String reg,String make,String model,String type,int year,java.math.BigDecimal rate,String status,String notes)throws SQLException{if(id==0){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO vehicles(registration_number,make,model,vehicle_type,model_year,daily_rate,status,notes) VALUES(?,?,?,?,?,?,?,?)")){bind(p,reg,make,model,type,year,rate,status,notes);p.executeUpdate();}}else try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE vehicles SET registration_number=?,make=?,model=?,vehicle_type=?,model_year=?,daily_rate=?,status=?,notes=? WHERE id=?")){bind(p,reg,make,model,type,year,rate,status,notes);p.setLong(9,id);if(p.executeUpdate()==0)throw new SQLException("Vehicle not found.");}}
 private void bind(PreparedStatement p,String reg,String make,String model,String type,int year,java.math.BigDecimal rate,String status,String notes)throws SQLException{p.setString(1,reg);p.setString(2,make);p.setString(3,model);p.setString(4,type);p.setInt(5,year);p.setBigDecimal(6,rate);p.setString(7,status);p.setString(8,notes);}
 public void deactivate(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE vehicles SET status='INACTIVE' WHERE id=? AND status<>'RENTED' AND NOT EXISTS(SELECT 1 FROM rentals r WHERE r.vehicle_id=vehicles.id AND r.status IN ('BOOKED','ACTIVE'))")){p.setLong(1,id);if(p.executeUpdate()==0)throw new SQLException("Vehicle is currently booked/rented or was not found; it cannot be deactivated.");}}
}
